def main() -> None:
    sample = pd.read_csv(OUT / "02_표집.csv", encoding="utf-8-sig")
    pilot = sample[sample["표본구분"] == "시험"][["표본번호", "comment_id", "post_id", "account_id", "층"]].copy()
    if set(pilot["표본번호"]) != set(range(1, 85)):
        raise SystemExit("시험 번호가 1–84가 아니다")
    linked = {row[0] for row in R}
    missing = [n for n in range(1, 85) if n not in INVALID and n not in linked]
    extra = [n for n in INVALID if n in linked]
    if missing or extra:
        raise SystemExit(f"누락 {missing} 중복 {extra}")
    cols = ["표본번호", "소비대상", "상품세부명", "인형기준", "관련작품", "관련캐릭터", "소비방식", "행동근거", "주체", "시간", "부정", "원문근거", "제목보조", "모호성", "직접연결"]
    links = pd.DataFrame(R, columns=cols)
    links.insert(0, "관계순번", links.groupby("표본번호").cumcount() + 1)
    links = pilot.merge(links, on="표본번호", how="right")
    links["판정방법"] = "에이전트 읽기"
    links["판정버전"] = VER
    links["표본구분"] = "시험"
    comments = pilot.copy()
    comments["유효소비"] = comments["표본번호"].map(lambda n: "아니오" if n in INVALID else "예")
    comments["무효사유"] = comments["표본번호"].map(lambda n: INVALID.get(n, ""))
    comments["관계수"] = comments["표본번호"].map(lambda n: int((links["표본번호"] == n).sum()))
    comments["판정방법"] = "에이전트 읽기"
    comments["판정버전"] = VER
    comments["표본구분"] = "시험"
    comments.to_csv(OUT / "03_시험판정_댓글.csv", index=False, encoding="utf-8-sig")
    links.to_csv(OUT / "03_시험판정_연결.csv", index=False, encoding="utf-8-sig")
    print("댓글", len(comments), "유효", int((comments["유효소비"] == "예").sum()), "관계", len(links))


if __name__ == "__main__":
    main()
